149	func TestResolveConcreteMethodBeatsWildcard(t *testing.T) {
150		cfg := mustConfig(t, `{
151		  "routes": [
152		    {"id": "wide",   "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://wide.internal"},
153		    {"id": "exact",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://exact.internal"}
154		  ]
155		}`)
156	
157		res := resolveJSON(t, cfg, `{"method":"GET","target":"/things/1"}`)
158		if res.RouteID != "exact" {
159			t.Fatalf("routeId = %q, want exact (concrete method wins)", res.RouteID)
160		}
161	
162		// A non-GET request can only use the wildcard route.
163		res = resolveJSON(t, cfg, `{"method":"POST","target":"/things/1"}`)
164		if res.RouteID != "wide" {
165			t.Fatalf("routeId = %q, want wide", res.RouteID)
166		}
167	
168		// Method names are case-sensitive: a concrete "GET" route must not match "get".
169		getOnly := mustConfig(t, `{"routes":[
170		  {"id":"only-get","methods":["GET"],"pathPrefix":"/things","upstream":"http://g.internal"}]}`)
171		if _, rf := Resolve(getOnly, mustReq(t, "get", "/things/1")); rf == nil || rf.Code != "route_not_found" {
172			t.Fatalf("got %+v, want route_not_found for lowercase method", rf)
173		}
174		// ...but a wildcard route does accept any legal method token, incl. "get".
175		res = resolveJSON(t, cfg, `{"method":"get","target":"/things/1"}`)
176		if res.RouteID != "wide" {
177			t.Fatalf("routeId = %q, want wide (wildcard matches any legal method)", res.RouteID)
178		}
179	}
