181	func TestResolveConflict(t *testing.T) {
182		cfg := mustConfig(t, `{
183		  "routes": [
184		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://z.internal"},
185		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://a.internal"},
186		    {"id": "mid",   "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://m.internal"}
187		  ]
188		}`)
189		req, f := ParseRequest([]byte(`{"method":"GET","target":"/things"}`))
190		if f != nil {
191			t.Fatalf("unexpected request failure: %+v", f)
192		}
193		_, rf := Resolve(cfg, req)
194		if rf == nil {
195			t.Fatal("expected route_conflict")
196		}
197		if rf.Code != "route_conflict" {
198			t.Fatalf("code = %q, want route_conflict", rf.Code)
199		}
200		want := []string{"alpha", "mid", "zeta"}
201		if len(rf.Candidates) != len(want) {
202			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
203		}
204		for i := range want {
205			if rf.Candidates[i] != want[i] {
206				t.Fatalf("candidates = %v, want sorted %v", rf.Candidates, want)
207			}
208		}
209	
210		// Concrete vs wildcard at same prefix is NOT a conflict.
211		cfg2 := mustConfig(t, `{
212		  "routes": [
213		    {"id": "b-wild", "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://w.internal"},
214		    {"id": "a-get",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://g.internal"}
215		  ]
216		}`)
217		res := resolveJSON(t, cfg2, `{"method":"GET","target":"/things/x"}`)
218		if res.RouteID != "a-get" {
219			t.Fatalf("routeId = %q, want a-get", res.RouteID)
220		}
221	
222		// Two wildcards with no concrete entry remain a conflict.
223		cfg3 := mustConfig(t, `{
224		  "routes": [
225		    {"id": "w1", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w1.internal"},
226		    {"id": "w2", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w2.internal"}
227		  ]
228		}`)
229		_, rf = Resolve(cfg3, mustReq(t, "POST", "/things/x"))
230		if rf == nil || rf.Code != "route_conflict" {
231			t.Fatalf("got %+v, want route_conflict between wildcard routes", rf)
232		}
233	}
