343	func TestEncodedPrefixBoundary(t *testing.T) {
344		// A prefix that itself contains an encoded slash is matched against the
345		// raw target; the encoded slash is data in the same segment.
346		cfg := mustConfig(t, `{
347		  "routes": [
348		    {"id": "encoded", "methods": ["*"], "pathPrefix": "/files/a%2Fb", "upstream": "http://files.internal/f"}
349		  ]
350		}`)
351		res := resolveJSON(t, cfg, `{"method":"GET","target":"/files/a%2Fb/x"}`)
352		if res.RouteID != "encoded" || res.UpstreamURL != "http://files.internal/f/x" {
353			t.Fatalf("got %+v", res)
354		}
355		if _, f := Resolve(cfg, mustReq(t, "GET", "/files/a/b/x")); f == nil || f.Code != "route_not_found" {
356			t.Fatalf("got %+v, want not found: literal slash must not match %%2F prefix", f)
357		}
358	}
