360	func TestResolutionJSONShape(t *testing.T) {
361		cfg := mustConfig(t, `{"routes":[{"id":"r1","methods":["GET"],"pathPrefix":"/","upstream":"http://h"}]}`)
362		res := resolveJSON(t, cfg, `{"method":"GET","target":"/p?q=1"}`)
363		out, err := json.Marshal(res)
364		if err != nil {
365			t.Fatal(err)
366		}
367		if string(out) != `{"routeId":"r1","upstreamURL":"http://h/p?q=1"}` {
368			t.Fatalf("json = %s", out)
369		}
370	}
371	
372	func TestFailureJSONShape(t *testing.T) {
373		f := failuref("route_conflict", "boom")
374		f.Candidates = []string{"b", "a"}
375		out, _ := json.Marshal(f)
376		var got map[string]any
377		if err := json.Unmarshal(out, &got); err != nil {
378			t.Fatal(err)
379		}
380		if got["code"] != "route_conflict" || got["reason"] != "boom" {
381			t.Fatalf("unexpected json: %s", out)
382		}
383	}
