func TestQueryTransformExample(t *testing.T) {
	cfg := qtConfig(t, `[{"op":"set","name":"a","value":""},{"op":"remove","name":"flag"}]`)
	got := qtResolve(t, cfg, "/api?x=%2f&a=1&%61=2&flag")
