	// config is still invalid.
	src := `{"routes":[
		{"id":"good","methods":["*"],"pathPrefix":"/api","upstream":"http://h/good"},
		{"id":"bad","methods":["*"],"pathPrefix":"/other","upstream":"http://h/bad",
		 "queryTransforms":[{"op":"nope","name":"a"}]}
	]}`
