	if f == nil || f.Code != "invalid_config" {
		t.Fatalf("got %+v, want invalid_config", f)
	}
	if !strings.Contains(f.Reason, "route 2") {
		t.Fatalf("reason = %q should locate route 2", f.Reason)
	}
}

